INSERT INTO articulos (
  slug, titulo, extracto, contenido, imagen_destacada, estado, metadata, created_at, updated_at, categoria_id, autor_id
) VALUES (
  'los-mandatos-del-rey', 'Los Mandatos del Rey', 'Juego de desplazamiento, imitación corporal y atención donde los scouts avanzan hacia el Rey imitando a personajes y estatuas hasta petrificarse al girarse el soberano.', '<h2>📜 Descripción de Los Mandatos del Rey</h2>
<p><b>Los Mandatos del Rey</b> es un juego activo de desplazamiento expresivo, control del movimiento y respuesta refleja. En esta dinámica, un scout o dirigente asume el papel del <i>Rey</i> colocándose en el extremo opuesto del terreno. Los demás participantes se sitúan en la línea de partida y deben avanzar hacia el monarca imitando los desplazamientos y sonidos del personaje u objeto que el Rey ordene en cada mandato (ej. <i>¡El Rey manda que todos me sigan como robots!</i>), debiendo quedar petrificados instantáneamente cada vez que el Rey se gira.</p>
<p>Este juego estimula la desinhibición, la agilidad de reacción y el fair play en Manada, Compañía y Tropa.</p>

<h2>🎲 ¿Cómo se juega Los Mandatos del Rey?</h2>
<p>Para llevar a cabo el juego de forma fluida y ordenada, se deben seguir los siguientes pasos:</p>
<ul>
  <li><b>Disposición en la Pista:</b> El participante designado como el <i>Rey</i> se coloca de espaldas al grupo en un extremo de la cancha o terreno de juego. Los beneficiarios se alinean en el extremo opuesto.</li>
  <li><b>El Mandato Real:</b> El Rey proclama en voz alta: <i>“El Rey ordena que todos avancen como...”</i> especificando una figura (ej. leones, gigantes, enanos, astronautas, automóviles o canguros).</li>
  <li><b>Desplazamiento e Imitación:</b> Los jugadores avanzan en dirección al Rey imitando de forma teatral los movimientos y sonidos del personaje indicado.</li>
  <li><b>El Giro de Petrificación:</b> En cualquier momento, el Rey se da la vuelta rápidamente. Al girarse, todos los jugadores deben congelarse inmóviles en su lugar. Si el Rey descubre a alguien moviéndose o sin caracterizar el mandato, esa persona debe regresar a la línea de salida.</li>
  <li><b>La Corona del Triunfo:</b> El primer participante que logre avanzar sin ser detectado y toque suavemente el hombro del Rey se declara ganador y asume la corona como el nuevo Rey para la siguiente ronda.</li>
</ul>

<h2>🏆 Cómputo de Puntos y Condición de Victoria de Los Mandatos del Rey</h2>
<p>La actividad combina velocidad y control corporal. Se pueden asignar los siguientes reconocimientos en el Tally:</p>
<ul>
  <li><b>Toque Real Ganador:</b> Otorgar 5 puntos a la patrulla o seisena del participante que alcance al Rey en primer lugar.</li>
  <li><b>Mejor Caracterización de Mandato:</b> Otorgar 3 puntos al jugador que realice la imitación más expresiva y divertida durante el avance.</li>
  <li><b>Inmovilidad Absoluta:</b> Otorgar 3 puntos a la unidad que mantenga el mejor equilibrio y temple al momento del giro del soberano.</li>
</ul>', '/uploads/los-mandatos-del-rey.webp', 'publicado', '{"areas": ["corporalidad", "creatividad", "carácter"], "unidades": ["manada", "compañía", "tropa"], "duracion": "15 minutos", "cantidad": "04 participantes", "lugares": ["Interior", "Exterior"], "materiales": ["Sin Materiales"], "objetivos": ["Desarrollo de la expresión corporal", "Estimular la agilidad mental", "Desfogue de Energías", "Respeto a las reglas del juego"], "justificacion_areas": "Los Mandatos del Rey desarrolla la corporalidad al exigir la adaptación biomecánica constante del paso y el freno brusco de inercia motor. Promueve la creatividad al incentivar la interpretación gestual instantánea de diversos personajes y objetos en movimiento. Fortalece el carácter al entrenar la autocontención física y la aceptación honesta de las reglas cuando se debe retornar a la salida.", "variaciones": "<b>Reyes Múltiples Simultáneos:</b> Designar a dos Reyes en los extremos del campo que emitan órdenes contradictorias obligando a los scouts a dividir su atención.<br><b>Mandatos en Clave Scout:</b> El Rey ordena desplazamientos asociados a técnicas scout (ej. avanzar haciendo nudos imaginarios, rastreando pistas o navegando con brújula).<br><b>El Rey Silencioso:</b> El Rey muestra tarjetas con imágenes de los personajes en lugar de proclamar el mandato vocalmente.", "recomendaciones": "Garantizar que el terreno de juego esté completamente despejado y nivelado para evitar tropezones durante los desplazamientos acelerados. Fomentar la honestidad scout para que los participantes que sean detectados en movimiento regresen por cuenta propia a la línea de partida. Variar la velocidad de los giros del Rey para mantener la emoción del grupo.", "objetivos_educativos": [{"id": "a0c0e5c9-aba9-43be-8ce2-53bc4ede06b5", "area": "Corporalidad", "unidad": "Manada", "texto": "Me gusta practicar deportes.", "como_se_cumple": "Ejercitando la agilidad de carrera y la capacidad de freno motor brusco."}, {"id": "309c6121-94fc-43a2-b0fb-f6a975f78962", "area": "Corporalidad", "unidad": "Manada", "texto": "Practico deportes, conozco sus reglas y sé perder.", "como_se_cumple": "Afinando el equilibrio físico al detener la inercia en la postura ordenada."}, {"id": "1427451e-b8b3-493b-8525-e53298381e07", "area": "Corporalidad", "unidad": "Compañía", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "como_se_cumple": "Respetando las normas de avance y manteniendo el control postural estricto."}, {"id": "b12da732-d736-480c-82b8-95b312316390", "area": "Corporalidad", "unidad": "Compañía", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "como_se_cumple": "Demostrando rapidez refleja y coordinación física durante los avances."}, {"id": "0765469b-caef-4457-9d6b-cb739c855402", "area": "Corporalidad", "unidad": "Tropa", "texto": "Conozco y practico diferentes juegos y respeto sus reglas.", "como_se_cumple": "Desarrollando la motricidad adaptativa y el control corporal en frenados secos."}, {"id": "08369c53-2c02-4e9c-8bb5-f949cd092c98", "area": "Corporalidad", "unidad": "Tropa", "texto": "Me esfuerzo por mejorar mi rendimiento en el deporte que practico y sé ganar y perder.", "como_se_cumple": "Exigiendo la máxima precisión estática e inmovilidad neuromuscular ante el giro."}, {"id": "ec280dd0-2d80-4b84-86ad-2d362da14886", "area": "Creatividad", "unidad": "Manada", "texto": "Me gusta participar en juegos de observación.", "como_se_cumple": "Observando los movimientos del Rey para anticipar el momento de su giro."}, {"id": "dcdcce42-6b31-45f7-a135-290f0f74b5a6", "area": "Creatividad", "unidad": "Manada", "texto": "Me gustan los juegos en que tengo que usar mi agilidad mental.", "como_se_cumple": "Improvisando de forma instantánea los gestos característicos del mandato real."}, {"id": "e1b7276f-4fd2-4c39-a32a-bd7fadbee702", "area": "Creatividad", "unidad": "Compañía", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Expresando creatividad e iniciativa al interpretar los personajes ordenados."}, {"id": "0009f64a-0654-46bf-b6fc-7b9d7f278485", "area": "Creatividad", "unidad": "Compañía", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Analizando las trayectorias de avance con menor riesgo de visibilidad."}, {"id": "49ae6ac6-be8f-4f2c-8b3e-6711d041181f", "area": "Creatividad", "unidad": "Tropa", "texto": "Doy mi opinión sobre las cosas que me pasan.", "como_se_cumple": "Demostrando desenvoltura y soltura dramática en los desplazamientos."}, {"id": "3d0dff9b-11cd-4a30-b3a6-ec011ad95062", "area": "Creatividad", "unidad": "Tropa", "texto": "Puedo analizar una situación desde distintos puntos de vista.", "como_se_cumple": "Diseñando estrategias de acercamiento sigiloso adaptadas al mandato."}, {"id": "041daaea-c4a7-472b-a613-951bd25cfa85", "area": "Carácter", "unidad": "Manada", "texto": "Reconozco y acepto mis errores.", "como_se_cumple": "Aceptando con alegría y caballerosidad retornar a la salida al ser detectado."}, {"id": "4df1ba93-06fe-4f49-b273-fddc3800cf17", "area": "Carácter", "unidad": "Manada", "texto": "Le doy importancia a las cosas que hago bien.", "como_se_cumple": "Valorando el propio esfuerzo de autocontrol postural frente a la tentación de avanzar."}, {"id": "2cc128e0-7cc6-49df-a7c5-825f6ab79793", "area": "Carácter", "unidad": "Compañía", "texto": "Sé que puedo ser cada día mejor.", "como_se_cumple": "Superando la prisa para perfeccionar el frenado y la inmovilidad en cada intento."}, {"id": "006c5b09-47cf-4ed8-bf25-212203261a03", "area": "Carácter", "unidad": "Compañía", "texto": "Sé que soy capaz de hacer cosas y de hacerlas bien.", "como_se_cumple": "Demostrando temple y seguridad en la consecución del objetivo."}, {"id": "62876ebe-214f-4caf-b164-664e12fd30ae", "area": "Carácter", "unidad": "Tropa", "texto": "Me gusta participar en actividades que me ayudan a conocerme.", "como_se_cumple": "Reconociendo los límites de estabilidad muscular propia ante frenazos repentinos."}, {"id": "78bd48d3-5d26-4218-843a-33712bade630", "area": "Carácter", "unidad": "Tropa", "texto": "Sé que soy capaz de hacer cosas y de hacerlas bien.", "como_se_cumple": "Liderando el rol del Rey con equidad, justicia y respeto hacia todos los participantes."}]}'::jsonb, NOW(), NOW(), NULL, NULL
);

